// High-reliability embedded PDF resume utility
// Guaranteed to download authentic binary PDF without server MIME or SPA routing issues

export const RESUME_PDF_BASE64 = '';

/**
 * Creates a valid, pristine Blob from embedded base64 PDF data
 */
export function getResumePdfBlob(): Blob {
  const binaryString = atob(RESUME_PDF_BASE64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return new Blob([bytes], { type: 'application/pdf' });
}

/**
 * Generates an active Blob URL for viewing or downloading the PDF
 */
export function getResumePdfBlobUrl(): string {
  const blob = getResumePdfBlob();
  return URL.createObjectURL(blob);
}

/**
 * Triggers an immediate, guaranteed direct download of the PDF to the user's local computer
 */
export function triggerDirectResumeDownload(filename = 'Ryan_Tomas_Resume.pdf'): void {
  try {
    const blob = getResumePdfBlob();
    const blobUrl = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = blobUrl;
    link.download = filename;
    link.style.display = 'none';
    document.body.appendChild(link);
    link.click();
    setTimeout(() => {
      document.body.removeChild(link);
      URL.revokeObjectURL(blobUrl);
    }, 1000);
  } catch (err) {
    console.error('Fallback download:', err);
    // Fallback to static public link
    const fallbackLink = document.createElement('a');
    fallbackLink.href = '/Ryan_Tomas_Resume.pdf';
    fallbackLink.download = filename;
    fallbackLink.target = '_blank';
    document.body.appendChild(fallbackLink);
    fallbackLink.click();
    setTimeout(() => document.body.removeChild(fallbackLink), 1000);
  }
}
